// Package sqlgen corresponds to Python structured/core/sql_generation/__init__.py.
// Prompt text is generated by tools/oracle/gen_prompts.py — do not edit prompts.go by hand.
package sqlgen

import (
	"context"
	"errors"
	"strings"

	"void2md/structured/pkg/chatmodel"
	"void2md/structured/pkg/jsonmin"
	"void2md/structured/pkg/sqlutil"
)

// Result corresponds to Python arun's (answer, sql, input_tokens, output_tokens, error)
// quintuple; Answer/Error are pointers for Python's None.
type Result struct {
	Answer       *string
	SQL          string
	InputTokens  int
	OutputTokens int
	Error        *string
}

// ErrMissingErrorMsg corresponds to Python's `assert error_msg, ...`.
var ErrMissingErrorMsg = errors.New("error_msg is required when you need to correct sql")

// Run corresponds to sql_generation.arun; non-empty errorSQL selects the correction branch,
// which requires non-nil errorMsg.
func Run(
	ctx context.Context,
	query string,
	llm chatmodel.ChatModel,
	dbInfo string,
	evidence string,
	errorSQL *string,
	errorMsg *string,
) (Result, error) {
	data := map[string]string{
		"db_info":      dbInfo,
		"user_query":   query,
		"current_time": sqlutil.GetBeijingTime("%Y-%m-%d %H:%M:%S"),
		"evidence":     evidence,
	}

	tmpl := promptPrefix
	// Python `if not error_sql:` — empty string is falsy too.
	if errorSQL == nil || *errorSQL == "" {
		tmpl += generationPrompt
	} else {
		if errorMsg == nil {
			return Result{}, ErrMissingErrorMsg
		}
		data["current_sql"] = *errorSQL
		data["error"] = *errorMsg
		tmpl += correctionPrompt
	}

	prompt, err := sqlutil.PyFormat(tmpl, data)
	if err != nil {
		return Result{}, err
	}

	resp, chatErr := llm.AInvoke(ctx, prompt)
	if chatErr != nil {
		// Python: `raise ValueError(err.msg)`
		return Result{}, errors.New(chatErr.Msg)
	}

	content := resp.Content
	var answer *string
	sql := ""

	switch {
	case strings.HasPrefix(content, "SELECT"):
		sql = content
	case strings.Contains(content, "```sql"):
		// Python: content.split("```sql")[1].split("```")[0]
		rest := strings.SplitN(content, "```sql", 2)[1]
		sql = strings.SplitN(rest, "```", 2)[0]
	default:
		// Python's text2json (json_repair) never raises JSONDecodeError in practice, so its
		// except branch is unreachable and Error is always nil.
		result := jsonmin.Text2JSON(content)
		if v, ok := result["answer"]; ok {
			s := sqlutil.PyTruthyString(v, true)
			answer = &s
		} else {
			sql = sqlutil.PyTruthyString(result["sql"], true)
		}
	}

	return Result{
		Answer:       answer,
		SQL:          sql,
		InputTokens:  resp.InputTokens,
		OutputTokens: resp.OutputTokens,
		Error:        nil,
	}, nil
}
